package ca.humber.stockbridge.model;
import jakarta.persistence.*;import org.springframework.security.core.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.UserDetails;import java.util.*;
@Entity @Table(name="app_users") public class AppUser implements UserDetails {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;public String fullName;@Column(unique=true,nullable=false) public String email;public String passwordHash;public String role="STAFF";public boolean active=true;public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority("ROLE_"+role));}public String getPassword(){return passwordHash;}public String getUsername(){return email;}public boolean isEnabled(){return active;}}